    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">xÔy</span> و <span dir=\"ltr\" class=\"expr pt\">yÔz</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">xÔy = 100°</span>  و  <span dir=\"ltr\" class=\"expr pt\">[Ou)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">xÔy</span>  و  <span dir=\"ltr\" class=\"expr pt\">[Ot)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">yÔz</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">tÔu.</span> نختار المنصّف لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: [Ou)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">xÔy</span>  و  <span dir=\"ltr\" class=\"expr pt\">xÔy = 100°.</span> و لماذا لا مجموع زوايا المثلّث ؟ لأنّها تحتاج مثلّثا، و لا مثلّث في هذا الشّكل."},{"quoi":"القاعدة","math":"منصّف زاوية يقسمها إلى زاويتين متقايستين، قيس كلّ منهما نصف قيسها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[Ou)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">xÔy</span>  و  <span dir=\"ltr\" class=\"expr pt\">xÔy = 100°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">uÔy = 100° : 2 = 50°</span>"},{"quoi":"القاعدة","math":"زاويتان متكاملتان مجموع قيسيهما <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">xÔy</span> و <span dir=\"ltr\" class=\"expr pt\">yÔz</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">xÔy = 100°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">yÔz = 180° - 100° = 80°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[Ot)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">yÔz</span>  و  <span dir=\"ltr\" class=\"expr pt\">yÔz = 80°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">tÔy = 80° : 2 = 40°</span>"},{"quoi":"القاعدة","math":"إذا كانت زاويتان متجاورتين فإنّ قيس الزاوية الكبرى يساوي مجموع قيسيهما"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">uÔy</span> و <span dir=\"ltr\" class=\"expr pt\">tÔy</span> متجاورتان  و  <span dir=\"ltr\" class=\"expr pt\">uÔy = 50°</span>  و  <span dir=\"ltr\" class=\"expr pt\">tÔy = 40°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">tÔu = 50° + 40° = 90°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">tÔu = 90°</span>"}],
